#include <string>
#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    long long kMirror(int k, int n) {
        auto isPalindromeK = [&](long long val) -> bool {
            std::vector<int> digits;
            while (val > 0) {
                digits.push_back(val % k);
                val /= k;
            }
            int l = 0, r = (int)digits.size() - 1;
            while (l < r) {
                if (digits[l++] != digits[r--]) return false;
            }
            return true;
        };

        long long ans = 0;
        int count = 0;
        int length = 1;

        while (count < n) {
            int halfLen = (length + 1) / 2;
            long long start = std::pow(10, halfLen - 1);
            long long end = std::pow(10, halfLen);

            for (long long prefix = start; prefix < end; ++prefix) {
                std::string s = std::to_string(prefix);
                std::string rev = s;
                std::reverse(rev.begin(), rev.end());

                std::string fullStr = s + (length % 2 == 1 ? rev.substr(1) : rev);
                long long val = std::stoll(fullStr);

                if (isPalindromeK(val)) {
                    ans += val;
                    count++;
                    if (count == n) return ans;
                }
            }
            length++;
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public long kMirror(int k, int n) {
        long ans = 0;
        int count = 0;
        int length = 1;

        while (count < n) {
            int halfLen = (length + 1) / 2;
            long start = (long) Math.pow(10, halfLen - 1);
            long end = (long) Math.pow(10, halfLen);

            for (long prefix = start; prefix < end; prefix++) {
                String s = Long.toString(prefix);
                StringBuilder sb = new StringBuilder(s).reverse();

                String full = s + (length % 2 == 1 ? sb.substring(1) : sb.toString());
                long val = Long.parseLong(full);

                if (isPalindromeK(val, k)) {
                    ans += val;
                    count++;
                    if (count == n) return ans;
                }
            }
            length++;
        }
        return ans;
    }

    private boolean isPalindromeK(long val, int k) {
        List<Integer> digits = new ArrayList<>();
        while (val > 0) {
            digits.add((int) (val % k));
            val /= k;
        }
        int l = 0, r = digits.size() - 1;
        while (l < r) {
            if (!digits.get(l++).equals(digits.get(r--))) return false;
        }
        return true;
    }
}

